import Foundation
import GRDB

final class LocalTransactionRepository: TransactionRepository, @unchecked Sendable {
    private let database:AppDatabase;private let encoder=JSONEncoder();private let decoder=JSONDecoder()
    init(database:AppDatabase){self.database=database;encoder.dateEncodingStrategy = .iso8601;decoder.dateDecodingStrategy = .iso8601}
    func createOffline(_ item:FinanceTransaction)async throws{let payload=try encoder.encode(item);try await database.writer.write{db in try LocalTransactionRecord(item).insert(db);try OperationRecord(id:item.clientOperationId.uuidString,entity:"transaction",action:"create",payload:payload,state:SyncState.pending.rawValue,attempts:0,lastError:nil,createdAt:.now).insert(db)}}
    func recent(bookId:UUID,limit:Int)async throws->[FinanceTransaction]{try await database.writer.read{db in try LocalTransactionRecord.filter(Column("bookId")==bookId.uuidString).order(Column("transactionDate").desc).limit(limit).fetchAll(db).map{$0.domain}}}
    func pendingOperations(limit:Int)async throws->[SyncOperation]{try await database.writer.read{db in try OperationRecord.filter(sql:"state IN (?, ?)",arguments:[SyncState.pending.rawValue,SyncState.failed.rawValue]).order(Column("createdAt")).limit(limit).fetchAll(db).map{try SyncOperation(operationId:UUID(uuidString:$0.id)!,entity:$0.entity,action:$0.action,payload:decoder.decode(FinanceTransaction.self,from:$0.payload))}}}
    func setOperation(_ id:UUID,state:SyncState,message:String?)async throws{try await database.writer.write{db in try db.execute(sql:"UPDATE sync_operations SET state=?,attempts=attempts+1,lastError=? WHERE id=?",arguments:[state.rawValue,message,id.uuidString]);try db.execute(sql:"UPDATE local_transactions SET syncState=? WHERE clientOperationId=?",arguments:[state.rawValue,id.uuidString])}}
    func syncCursor(bookId:UUID)async throws->String{try await database.writer.read{db in try String.fetchOne(db,sql:"SELECT cursor FROM sync_cursors WHERE bookId=?",arguments:[bookId.uuidString]) ?? "0"}}
    func applyServerChanges(_ changes:[SyncChange],cursor:String,bookId:UUID)async throws{try await database.writer.write{db in for change in changes where change.entityType=="TRANSACTION"&&change.action=="UPSERT"{let record=try LocalTransactionRecord(change.payload);try db.execute(sql:"DELETE FROM local_transactions WHERE clientOperationId=? AND id<>?",arguments:[record.clientOperationId,record.id]);try record.save(db)};try db.execute(sql:"INSERT INTO sync_cursors(bookId,cursor)VALUES(?,?) ON CONFLICT(bookId)DO UPDATE SET cursor=excluded.cursor",arguments:[bookId.uuidString,cursor])}}
}
private extension LocalTransactionRecord{init(_ x:FinanceTransaction){self.init(id:x.id.uuidString,bookId:x.bookId.uuidString,type:x.type.rawValue,title:x.title,amount:x.amount.decimalString,currencyCode:x.currencyCode,accountId:x.accountId.uuidString,targetAccountId:x.targetAccountId?.uuidString,categoryId:x.categoryId?.uuidString,contactId:x.contactId?.uuidString,transactionDate:x.transactionDate,dueDate:x.dueDate,details:x.details,clientOperationId:x.clientOperationId.uuidString,serverVersion:x.serverVersion,syncState:x.syncState.rawValue)}var domain:FinanceTransaction{get throws{FinanceTransaction(id:UUID(uuidString:id)!,bookId:UUID(uuidString:bookId)!,type:TransactionType(rawValue:type)!,title:title,amount:try Money(amount),currencyCode:currencyCode,accountId:UUID(uuidString:accountId)!,targetAccountId:targetAccountId.flatMap{UUID(uuidString:$0)},categoryId:categoryId.flatMap{UUID(uuidString:$0)},contactId:contactId.flatMap{UUID(uuidString:$0)},transactionDate:transactionDate,dueDate:dueDate,details:details,clientOperationId:UUID(uuidString:clientOperationId)!,serverVersion:serverVersion,syncState:SyncState(rawValue:syncState)!)}}}
private extension LocalTransactionRecord{init(_ x:ServerTransaction)throws{self.init(id:x.id.uuidString,bookId:x.bookId.uuidString,type:x.type.rawValue,title:x.title,amount:x.amount,currencyCode:x.currencyCode,accountId:x.accountId?.uuidString ?? UUID().uuidString,targetAccountId:nil,categoryId:nil,contactId:nil,transactionDate:x.transactionDate,dueDate:nil,details:nil,clientOperationId:x.clientOperationId.uuidString,serverVersion:x.version,syncState:SyncState.synced.rawValue)}}
